<template>
  <view class="page"><view class="points-card" :class="levelClass"><view class="user"><image :src="avatar" mode="aspectFill"/><view><text>{{ username }}</text><text class="ui-small">{{ memberLevel }}</text></view></view><view class="points"><text class="ui-small">我的积分</text><text class="ui-strong">{{ points }}</text></view></view><scroll-view scroll-x class="category-scroll" show-scrollbar="false"><view class="categories"><view v-for="item in categories" :key="item.id" class="category" :class="{ active: Number(activeCategoryId) === Number(item.id) }" @tap="chooseCategory(item.id)">{{ item.name }}</view></view></scroll-view><view v-if="loading" class="state">加载中...</view><view v-else-if="!products.length" class="state">暂无积分商品</view><view v-else class="grid"><view v-for="item in products" :key="item.id" class="item" @tap="open(item)"><image :src="item.cover_image || '/static/navigation/sravx-mark.png'" mode="aspectFill"/><view class="level" :class="{ locked: !item.can_redeem }">{{ item.min_member_level_name }}可兑</view><text class="name">{{ item.short_name || item.name }}</text><text class="cost">{{ item.points_price }} 积分</text><text v-if="!item.can_redeem" class="lock-tip">当前等级不可兑换</text></view></view></view>
</template>
<script>
import api from '../../common/api.js'
import auth from '../../common/auth.js'
const levelNames = { 1: 'LV1', 2: 'LV2', 3: 'LV3', 4: 'LV4', 5: 'LV5', 6: 'LV6' }
const levelClasses = { 1: 'normal', 2: 'silver', 3: 'gold', 4: 'diamond', 5: 'black-diamond', 6: 'supreme' }
export default { data() { return { points: 0, username: 'Sravx 用户', avatar: '/static/navigation/sravx-mark.png', memberLevel: 'LV1', levelClass: 'normal', products: [], categories: [], activeCategoryId: 0, loading: true } }, onLoad() { this.load() }, onPullDownRefresh() { this.load().finally(() => uni.stopPullDownRefresh()) }, methods: { async load() { this.loading = true; try { const current = auth.user(); const [userResult, productsResult] = await Promise.all([current && current.phone ? api.getUserInfo().catch(() => null) : Promise.resolve(null), api.getPointsProducts(this.activeCategoryId).catch(() => ({ products: [], categories: [] }))]); const mall = Array.isArray(productsResult) ? { products: productsResult, categories: [] } : productsResult || {}; const level = Number(userResult && userResult.member_level || mall.current_member_level || 1) || 1; this.points = userResult && userResult.points || 0; this.username = userResult && (userResult.nickname || userResult.username) || 'Sravx 用户'; this.avatar = userResult && userResult.avatar || '/static/navigation/sravx-mark.png'; this.memberLevel = levelNames[level] || 'LV1'; this.levelClass = levelClasses[level] || 'normal'; this.categories = [{ id: 0, name: '全部' }].concat(Array.isArray(mall.categories) ? mall.categories : []); this.products = (mall.products || []).map(item => { const min = Number(item.min_member_level || 1) || 1; return { ...item, min_member_level: min, min_member_level_name: item.min_member_level_name || levelNames[min] || 'LV1', can_redeem: item.can_redeem !== false } }) } catch (error) { uni.showToast({ title: '加载失败', icon: 'none' }) } finally { this.loading = false } }, chooseCategory(id) { const next = Number(id) || 0; if (next === Number(this.activeCategoryId)) return; this.activeCategoryId = next; this.load() }, open(item) { if (!item.id) return; if (!item.can_redeem) return uni.showToast({ title: `需${item.min_member_level_name || '更高会员等级'}可兑换`, icon: 'none' }); uni.navigateTo({ url: `/pages/points-product-detail/index?id=${item.id}` }) } } }
</script>
<style>
.page{min-height:100vh;padding:12px;box-sizing:border-box;background:#F4F6F8}.points-card{position:relative;display:flex;align-items:center;justify-content:space-between;min-height:95px;padding:17px 14px;overflow:hidden;border-radius:10px;background:linear-gradient(135deg,#232326,#151518);box-sizing:border-box;color:#fff;box-shadow:0 7px 17px rgba(0,0,0,.18)}.points-card.silver{background:linear-gradient(135deg,#26262a,#141417)}.points-card.gold{background:linear-gradient(135deg,#2B3037,#141417)}.points-card.diamond{background:linear-gradient(135deg,#0B0D10,#121216)}.points-card.black-diamond{background:linear-gradient(135deg,#171719,#0f0f12)}.points-card.supreme{background:linear-gradient(135deg,#241624,#0f0f12)}.user{display:flex;align-items:center;max-width:60%}.user image{width:43px;height:43px;margin-right:9px;border-radius:50%;background:#2c2c2e}.user text,.user .ui-small,.points .ui-small,.points .ui-strong{display:block}.user text{font-size:15px;font-weight:650}.user .ui-small,.points .ui-small{margin-top:3px;color:#d2d2d7;font-size:11px}.points{text-align:right}.points .ui-strong{margin-top:3px;font-size:27px}.category-scroll{margin:10px 0}.categories{display:inline-flex;gap:7px}.category{padding:8px 12px;border-radius:16px;background:#fff;color:#5b5b62;font-size:12px;white-space:nowrap}.category.active{background:#0B0D10;color:#fff}.state{padding:40px 0;text-align:center;color:#636366;font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.item{position:relative;overflow:hidden;padding-bottom:9px;border-radius:8px;background:#fff}.item image{width:100%;height:130px;background:#eee}.level{position:absolute;left:6px;top:6px;padding:4px 6px;border-radius:10px;background:rgba(29,29,31,.72);color:#fff;font-size:10px}.level.locked{background:rgba(168,120,42,.9)}.name,.cost,.lock-tip{display:block;padding:0 8px}.name{min-height:37px;margin-top:8px;font-size:14px;line-height:18px}.cost{color:#0B0D10;font-size:13px}.lock-tip{margin-top:3px;color:#4A4A4D;font-size:10px}
</style>
